// false — создать закрытым
var ready = new ManualResetEvent(false);
var next  = new AutoResetEvent(false);
var slots = new Semaphore(3, 3);  // 3 места из 3

// открыто для всех, пока не вызовут Reset()
ready.Set();
// пропустит один WaitOne и снова закроется
next.Set();

// занять место (или уснуть, пока мест нет)
slots.WaitOne();
// вернуть место из другого потока — можно
await Task.Run(() => slots.Release());

